/**
 * The components of the Chamfer design system, as functions that return class names, so that
 * they work in any framework. Every class has to be written out inside `cx(...)`, because the
 * stylesheet is generated by reading this file.
 */

export type ClassValue = string | false | null | undefined;

/** Joins class names, leaving out anything empty. */
export function cx(...parts: ClassValue[]): string {
  return parts.filter(Boolean).join(" ");
}

export type Tone = "neutral" | "brand" | "success" | "warning" | "danger" | "info";
export type Size = "sm" | "md" | "lg";

/** A clipped element can't show an outline, so it gives up its cut while it has focus. */
const focusRing = cx(
  "focus-visible:outline(2,accent) focus-visible:outline-offset(2) focus-visible:[clip-path:none]",
);

const motion = cx("transition(colors) duration(fast) motion-reduce:transition(none)");

/** The logo's slash, as a small mark in the current color. */
const slash = cx(
  "before:display(block) before:shrink(0) before:width[0.7em] before:height[0.4em] before:bg[currentColor] before:transform(skew-x(-42deg))",
);

/** Sets the page's colors and font. Put it on the body, or on any part of a page. */
export function page(className?: ClassValue): string {
  return cx("bg(ink) color(fg) font(sans) line-height(normal)", className);
}

// -------------------------------------------------------------------- Type

const headingSizes: Record<Size | "xl", string> = {
  sm: cx("text-size(xl)"),
  md: cx("text-size[clamp(1.5rem,3vw,2.25rem)]"),
  lg: cx("text-size[clamp(2rem,5vw,3.5rem)]"),
  xl: cx("text-size[clamp(3rem,9vw,8rem)]"),
};

/** A display heading in the wide face. */
export function heading(options: { size?: Size | "xl"; className?: ClassValue } = {}): string {
  return cx(
    "margin(0) font(display) [font-stretch:125%] text-weight(bold) letter-spacing(tighter) line-height[1.04]",
    headingSizes[options.size ?? "md"],
    options.className,
  );
}

/** A small mono label with the slash in front of it. */
export function eyebrow(className?: ClassValue): string {
  return cx(
    "display(flex) align(center) gap(3) margin(0) font(mono) text-size(xs) color(faint) text-transform(uppercase) letter-spacing(widest) before:color(accent)",
    slash,
    className,
  );
}

/** A key on a keyboard. */
export function kbd(className?: ClassValue): string {
  return cx(
    "display(inline-block) padding(0,2) font(mono) text-size(xs) line-height(relaxed) bg(raised) color(soft) border(1,line) border-bottom(2,line-strong)",
    className,
  );
}

// -------------------------------------------------------------------- Button

export type ButtonTone = "primary" | "secondary" | "ghost" | "danger";

const buttonTones: Record<ButtonTone, string> = {
  primary: cx("bg(brand) color(on-brand) hover:bg(fg) hover:color(ink)"),
  secondary: cx("bg(raised) color(fg) hover:bg(line-strong)"),
  ghost: cx("bg(transparent) color(soft) hover:bg(raised) hover:color(fg)"),
  danger: cx("bg(danger) color(on-danger) hover:bg(fg) hover:color(ink)"),
};

const buttonSizes: Record<Size, string> = {
  sm: cx("height[2rem] padding-x(3) text-size(xs)"),
  md: cx("height[2.5rem] padding-x(4) text-size(sm)"),
  lg: cx("height[3rem] padding-x(6) text-size(md)"),
};

export function button(
  options: { tone?: ButtonTone; size?: Size; block?: boolean; className?: ClassValue } = {},
): string {
  return cx(
    "display(inline-flex) align(center) justify(center) gap(2) box-sizing(border) margin(0) border(none) cut(sm) font(sans) text-weight(semibold) line-height(tight) text-decoration(none) whitespace(nowrap) cursor(pointer) user-select(none) active:transform(translate-y(1px)) disabled:opacity(50) disabled:cursor(not-allowed) disabled:pointer-events(none)",
    motion,
    focusRing,
    buttonTones[options.tone ?? "primary"],
    buttonSizes[options.size ?? "md"],
    options.block && cx("width(full)"),
    options.className,
  );
}

// -------------------------------------------------------------------- Badge

const badgeTones: Record<Tone, string> = {
  neutral: cx("bg(raised) color(soft)"),
  brand: cx("bg(brand) color(on-brand)"),
  success: cx("bg(alpha(success,14)) color(success)"),
  warning: cx("bg(alpha(warning,14)) color(warning)"),
  danger: cx("bg(alpha(danger,14)) color(danger)"),
  info: cx("bg(alpha(info,14)) color(info)"),
};

export function badge(options: { tone?: Tone; className?: ClassValue } = {}): string {
  return cx(
    "display(inline-flex) align(center) gap(2) padding(1,3) cut(xs) font(mono) text-size(xs) text-weight(medium) letter-spacing(wide) line-height(tight) whitespace(nowrap)",
    slash,
    badgeTones[options.tone ?? "neutral"],
    options.className,
  );
}

// -------------------------------------------------------------------- Card

export function card(options: { interactive?: boolean; className?: ClassValue } = {}): string {
  return cx(
    "position(relative) box-sizing(border) display(flex) flex-direction(col) gap(3) padding(6) bg(surface) color(fg) border(1,line) before:position(absolute) before:top[-1px] before:left[-1px] before:width[2.5rem] before:height[3px] before:bg(brand)",
    options.interactive && cx("hover:border-color(accent) hover:bg(raised) cursor(pointer)"),
    options.interactive && motion,
    options.className,
  );
}

export function cardTitle(className?: ClassValue): string {
  return cx("margin(0) text-size(lg) text-weight(semibold) line-height(snug)", className);
}

export function cardBody(className?: ClassValue): string {
  return cx("margin(0) text-size(sm) color(soft) line-height(relaxed)", className);
}

// -------------------------------------------------------------------- Alert

const alertTones: Record<Tone, string> = {
  neutral: cx("bg(raised) border-left(4,line-strong) color(fg)"),
  brand: cx("bg(alpha(accent,10)) border-left(4,accent) color(fg)"),
  success: cx("bg(alpha(success,10)) border-left(4,success) color(fg)"),
  warning: cx("bg(alpha(warning,10)) border-left(4,warning) color(fg)"),
  danger: cx("bg(alpha(danger,10)) border-left(4,danger) color(fg)"),
  info: cx("bg(alpha(info,10)) border-left(4,info) color(fg)"),
};

export function alert(options: { tone?: Tone; className?: ClassValue } = {}): string {
  return cx(
    "box-sizing(border) display(flex) flex-direction(col) gap(1) padding(4) text-size(sm) line-height(relaxed)",
    alertTones[options.tone ?? "neutral"],
    options.className,
  );
}

export function alertTitle(className?: ClassValue): string {
  return cx("margin(0) text-weight(semibold)", className);
}

// -------------------------------------------------------------------- Forms

/** Stacks a label, a control and its hint or error. */
export function field(className?: ClassValue): string {
  return cx("display(flex) flex-direction(col) gap(2)", className);
}

export function label(className?: ClassValue): string {
  return cx("font(sans) text-size(sm) text-weight(medium) color(fg)", className);
}

export function hint(className?: ClassValue): string {
  return cx("margin(0) text-size(xs) color(faint) line-height(snug)", className);
}

export function fieldError(className?: ClassValue): string {
  return cx("margin(0) text-size(xs) color(danger) line-height(snug)", className);
}

const control = cx(
  "box-sizing(border) width(full) margin(0) font(sans) text-size(sm) color(fg) bg(ink) border(1,line-strong) radius(none) hover:border-color(faint) focus:border-color(accent) focus-visible:outline(none) focus-visible:[box-shadow:inset_0_-2px_0_var(--croff-color-accent)] invalid:border-color(danger) disabled:opacity(50) disabled:cursor(not-allowed)",
);

export function input(className?: ClassValue): string {
  return cx(control, motion, "height[2.5rem] padding-x(3) placeholder:color(faint)", className);
}

export function textarea(className?: ClassValue): string {
  return cx(
    control,
    motion,
    "min-height[6rem] padding(3) line-height(relaxed) resize(y) placeholder:color(faint)",
    className,
  );
}

export function select(className?: ClassValue): string {
  return cx(
    control,
    motion,
    "height[2.5rem] padding-left(3) padding-right(8) appearance(none) cursor(pointer) bg-image[linear-gradient(45deg,transparent_50%,var(--croff-color-soft)_50%),linear-gradient(135deg,var(--croff-color-soft)_50%,transparent_50%)] bg-size[0.375rem_0.375rem] bg-position[right_1rem_center,right_0.625rem_center] bg-repeat(none)",
    className,
  );
}

/** A label holding a checkbox, radio button or switch beside its text. */
export function choice(className?: ClassValue): string {
  return cx(
    "display(inline-flex) align(center) gap(3) font(sans) text-size(sm) color(fg) cursor(pointer)",
    className,
  );
}

const toggle = cx(
  "appearance(none) box-sizing(border) margin(0) shrink(0) bg(ink) border(1,line-strong) cursor(pointer) hover:border-color(accent) disabled:opacity(50) disabled:cursor(not-allowed)",
);

/** Checked, it shows the logo's slash. */
export function checkbox(className?: ClassValue): string {
  return cx(
    toggle,
    motion,
    focusRing,
    "width[1.125rem] height[1.125rem] cut(xs) checked:border-color(brand) checked:bg(brand) checked:bg-image[linear-gradient(130deg,transparent_36%,var(--croff-color-on-brand)_36%,var(--croff-color-on-brand)_64%,transparent_64%)]",
    className,
  );
}

/** A diamond, to set it apart from a checkbox. */
export function radio(className?: ClassValue): string {
  return cx(
    toggle,
    motion,
    focusRing,
    "width[0.875rem] height[0.875rem] margin(0,1) transform(rotate(45deg)) checked:border-color(brand) checked:bg(brand) checked:bg-image[linear-gradient(var(--croff-color-on-brand),var(--croff-color-on-brand))] checked:bg-size[45%_45%] checked:bg-position(center) checked:bg-repeat(none)",
    className,
  );
}

/** Its thumb is a slash that slides across. Give the input role="switch". */
export function switchControl(className?: ClassValue): string {
  return cx(
    toggle,
    focusRing,
    "width[2.75rem] height[1.375rem] cut(xs) bg-image[linear-gradient(115deg,transparent_10%,var(--croff-color-soft)_10%,var(--croff-color-soft)_90%,transparent_90%)] bg-size[45%_100%] bg-repeat(none) bg-position(left) [transition:background-position_120ms,background-color_120ms] motion-reduce:[transition:none] checked:border-color(brand) checked:bg(brand) checked:bg-position(right) checked:bg-image[linear-gradient(115deg,transparent_10%,var(--croff-color-on-brand)_10%,var(--croff-color-on-brand)_90%,transparent_90%)]",
    className,
  );
}

// -------------------------------------------------------------------- Tabs

export function tabList(className?: ClassValue): string {
  return cx("display(flex) gap(1) overflow-x(auto) border-bottom(1,line)", className);
}

export function tab(className?: ClassValue): string {
  return cx(
    "margin-bottom[-1px] padding(3,4) bg(transparent) border(none) border-bottom(2,transparent) font(sans) text-size(sm) text-weight(medium) color(faint) whitespace(nowrap) cursor(pointer) hover:color(fg) selected:color(fg) selected:border-color(accent)",
    motion,
    focusRing,
    className,
  );
}

export function tabPanel(className?: ClassValue): string {
  return cx("padding-y(4) text-size(sm) color(soft) line-height(relaxed)", focusRing, className);
}

// -------------------------------------------------------------------- Dialog

/** For a native dialog element, which brings its own focus trap and Escape key. */
export function dialog(className?: ClassValue): string {
  return cx(
    "box-sizing(border) width[min(32rem,calc(100vw-2rem))] margin(auto) padding(6) bg(surface) color(fg) font(sans) border(1,line-strong) backdrop:bg(alpha(ink,80)) animation[croff-ui-rise_160ms_ease-out] motion-reduce:animation(none)",
    className,
  );
}

export function dialogTitle(className?: ClassValue): string {
  return cx(
    "margin(0) margin-bottom(3) font(display) [font-stretch:125%] text-size(xl) text-weight(bold) letter-spacing(tight) line-height(tight)",
    className,
  );
}

export function dialogBody(className?: ClassValue): string {
  return cx("margin(0) text-size(sm) color(soft) line-height(relaxed)", className);
}

export function dialogActions(className?: ClassValue): string {
  return cx("display(flex) flex-wrap(wrap) justify(end) gap(2) margin-top(6)", className);
}

// -------------------------------------------------------------------- Accordion

/** For a native details element. */
export function accordionItem(className?: ClassValue): string {
  return cx("border-bottom(1,line)", className);
}

export function accordionSummary(className?: ClassValue): string {
  return cx(
    "display(flex) align(center) justify(between) gap(4) padding-y(4) font(sans) text-size(sm) text-weight(medium) color(fg) cursor(pointer) list-style(none) details-marker:display(none) hover:color(accent)",
    motion,
    focusRing,
    className,
  );
}

/** A slash that lies flat when the item opens. */
export function accordionMarker(className?: ClassValue): string {
  return cx(
    "display(block) shrink(0) width[0.875rem] height[0.5rem] bg(accent) transform(skew-x(-42deg)) group-open:transform(skew-x(0deg)) group-open:height[0.125rem] [transition:transform_120ms,height_120ms] motion-reduce:[transition:none]",
    className,
  );
}

export function accordionBody(className?: ClassValue): string {
  return cx("padding-bottom(4) text-size(sm) color(soft) line-height(relaxed)", className);
}

// -------------------------------------------------------------------- Progress and loading

export function progress(className?: ClassValue): string {
  return cx("display(block) width(full) height[0.5rem] bg(raised) overflow(hidden)", className);
}

/** Set its width to the percentage done. */
export function progressBar(className?: ClassValue): string {
  return cx(
    "display(block) height(full) bg(accent) clip-path[polygon(0_0,100%_0,calc(100%-0.5rem)_100%,0_100%)] [transition:width_200ms_ease-out] motion-reduce:[transition:none]",
    className,
  );
}

/**
 * A slash that sweeps across its track, in the accent color. Set `inherit` to take the color of
 * what it sits on, as a spinner inside a button has to.
 */
export function spinner(options: { inherit?: boolean; className?: ClassValue } = {}): string {
  return cx(
    "display(inline-block) width[2.5em] height[0.5em] bg[color-mix(in_srgb,currentColor_20%,transparent)] transform(skew-x(-30deg)) bg-image[linear-gradient(currentColor,currentColor)] bg-size[40%_100%] bg-position(center) bg-repeat(none) animation[croff-ui-sweep_1s_ease-in-out_infinite] motion-reduce:animation(none)",
    !options.inherit && cx("color(accent)"),
    options.className,
  );
}

export function skeleton(className?: ClassValue): string {
  return cx(
    "display(block) height[1em] bg(raised) bg-image[linear-gradient(115deg,transparent_40%,var(--croff-color-line-strong)_50%,transparent_60%)] bg-size[250%_100%] bg-repeat(none) animation[croff-ui-sheen_1.4s_linear_infinite] motion-reduce:animation(none)",
    className,
  );
}

// -------------------------------------------------------------------- Avatar

const avatarSizes: Record<Size, string> = {
  sm: cx("width(8) height(8) text-size(xs)"),
  md: cx("width(10) height(10) text-size(sm)"),
  lg: cx("width(16) height(16) text-size(lg)"),
};

export function avatar(options: { size?: Size; className?: ClassValue } = {}): string {
  return cx(
    "display(inline-flex) align(center) justify(center) shrink(0) overflow(hidden) cut(sm) bg(raised) color(fg) font(mono) text-weight(semibold) text-transform(uppercase)",
    avatarSizes[options.size ?? "md"],
    options.className,
  );
}

export function avatarImage(className?: ClassValue): string {
  return cx("display(block) width(full) height(full) object-fit(cover)", className);
}

// -------------------------------------------------------------------- Table

export function tableWrap(className?: ClassValue): string {
  return cx("overflow-x(auto) border(1,line)", className);
}

export function table(className?: ClassValue): string {
  return cx(
    "width(full) border-collapse(collapse) font(sans) text-size(sm) color(soft) text-align(left)",
    className,
  );
}

export function tableCaption(className?: ClassValue): string {
  return cx("padding(3,4) text-align(left) text-size(xs) color(faint)", className);
}

export function tableHeader(className?: ClassValue): string {
  return cx(
    "padding(3,4) bg(raised) font(mono) text-size(xs) text-weight(medium) color(fg) text-transform(uppercase) letter-spacing(wider) whitespace(nowrap) border-bottom(1,line-strong)",
    className,
  );
}

export function tableRow(className?: ClassValue): string {
  return cx("hover:bg(raised)", className);
}

export function tableCell(className?: ClassValue): string {
  return cx("padding(3,4) border-bottom(1,line)", className);
}
